'use strict';
const fs=require('node:fs');
const path=require('node:path');
const file=path.resolve(__dirname,'../../tools/GUI_DEV/apple2-system-composer.html');
let html=fs.readFileSync(file,'utf8');
const bad='async async function importImageFiles(files){';
const good='async function importImageFiles(files){';
if(!html.includes(bad)) throw new Error('Expected duplicated async declaration was not found.');
if(html.indexOf(bad)!==html.lastIndexOf(bad)) throw new Error('Expected exactly one duplicated async declaration.');
html=html.replace(bad,good);
fs.writeFileSync(file,html);
console.log('Fixed duplicated async declaration.');
